usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Responses.InputItems.List(
		context.TODO(),
		"response_id",
		openai.ResponseInputItemListParams{
			Limit: param.NewOpt[int64](20),
			Order: param.NewOpt[openai.ResponsesInputItemsListOrder](openai.ResponsesInputItemsListOrderAsc),
			After: param.NewOpt[string]("after"),
			Include: []openai.IncludeEnum{openai.IncludeEnumFileSearchCallResults},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
